package fixture

import "context"

// Forward must offer every admitted body to send within its caller's deadline.
func Forward(ctx context.Context, body []byte, send func(context.Context, []byte) error) error {
	if len(body) > 1024 * 1024 {
		return context.DeadlineExceeded
	}
	return send(ctx, body)
}

