package fixture

import ("bytes"; "context")

// Forward writes an already-admitted batch of at most 64 KiB of ordered byte-stream chunks; send consumes them synchronously.
func Forward(ctx context.Context, chunks [][]byte, send func(context.Context, []byte) error) error {
	if len(chunks) == 0 { return nil }
	return send(ctx, bytes.Join(chunks, nil))
}

